function create_vector(x, y)
    local mt = {}
    mt.__index = mt
    function mt.__add(a, b)
        return create_vector(a.x + b.x, a.y + b.y)
    end
    function mt.__tostring(v)
        return "(" .. v.x .. ", " .. v.y .. ")"
    end
    return setmetatable({x = x, y = y}, mt)
end

function create_default(default_value)
    return setmetatable({}, {
        __index = function(t, key)
            return default_value
        end
    })
end

