function create_string_utils()
    local M = {}

    function M.trim(s)
        return s:match("^%s*(.-)%s*$")
    end

    function M.capitalize(s)
        return s:sub(1, 1):upper() .. s:sub(2)
    end

    function M.reverse_words(s)
        local words = {}
        for w in s:gmatch("%S+") do
            table.insert(words, w)
        end
        local result = {}
        for i = #words, 1, -1 do
            table.insert(result, words[i])
        end
        return table.concat(result, " ")
    end

    return M
end

