solution_code:
function create_stack()
    local Stack = {}
    Stack.__index = Stack

    function Stack.new()
        return setmetatable({data = {}}, Stack)
    end

    function Stack:push(value)
        table.insert(self.data, value)
    end

    function Stack:pop()
        if #self.data == 0 then return nil end
        return table.remove(self.data)
    end

    function Stack:peek()
        if #self.data == 0 then return nil end
        return self.data[#self.data]
    end

    function Stack:size()
        return #self.data
    end

    return Stack.new()
end

